<title>Wayne: The First Night</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800&family=DM+Mono:wght@400;500&display=swap');
:root{--gold:#e5b85c;--paper:#e9e5d9;--muted:#9ba4ad;--line:#ffffff22;--panel:#0b111be8}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#070b11;color:var(--paper);font-family:'Barlow Condensed',sans-serif}canvas{display:block;position:fixed;inset:0}.grain{pointer-events:none;position:fixed;inset:0;z-index:2;opacity:.11;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.35'/%3E%3C/svg%3E")}.vignette{position:fixed;inset:0;z-index:1;pointer-events:none;background:radial-gradient(ellipse at center,transparent 30%,#03060bc9 100%)}.hud{position:fixed;z-index:4;inset:0;pointer-events:none}.topbar{position:absolute;top:24px;left:30px;right:30px;display:flex;justify-content:space-between;align-items:flex-start}.brand{font-size:12px;letter-spacing:.28em;color:var(--gold);font-weight:700}.chapter{font:10px 'DM Mono';letter-spacing:.18em;color:#aab1b9;margin-top:5px}.status{border:1px solid var(--line);background:#080d15a8;padding:10px 14px;font:10px 'DM Mono';letter-spacing:.12em;color:#d5d9db}.status b{color:var(--gold);font-weight:400}.objective{position:absolute;left:30px;top:100px;width:230px;border-left:2px solid var(--gold);padding:4px 0 5px 13px}.eyebrow{font:9px 'DM Mono';letter-spacing:.2em;color:var(--gold);text-transform:uppercase}.objective h2{font-size:20px;letter-spacing:.04em;margin:4px 0 3px;font-weight:600}.objective p{font-size:14px;color:#aab0b5;margin:0;line-height:1.2}.bottom{position:absolute;left:30px;bottom:25px;display:flex;gap:8px;align-items:center;color:#aeb5ba;font:10px 'DM Mono';letter-spacing:.1em}.key{border:1px solid #ffffff3d;padding:5px 8px;color:#fff;background:#090e16aa}.interact{position:absolute;left:50%;bottom:16%;transform:translateX(-50%);padding:9px 16px;border:1px solid #e5b85c88;background:#090e16dd;color:var(--paper);font-size:14px;letter-spacing:.08em;opacity:0;transition:opacity .2s}.interact.show{opacity:1}.toast{position:absolute;right:30px;bottom:27px;font:10px 'DM Mono';letter-spacing:.12em;color:var(--gold);text-align:right}.dialogue{position:fixed;z-index:8;bottom:0;left:0;right:0;padding:24px max(28px,calc((100vw - 900px)/2)) 32px;background:linear-gradient(0deg,#070b11 70%,#070b11ee 88%,transparent);pointer-events:auto;display:none}.dialogue.show{display:block}.speaker{font:10px 'DM Mono';letter-spacing:.22em;color:var(--gold);margin-bottom:7px}.line{font-size:clamp(20px,3vw,27px);line-height:1.16;max-width:820px}.continue{margin-top:13px;font:10px 'DM Mono';letter-spacing:.16em;color:#9da5ad}.titleScreen,.storyScreen,.endScreen{position:fixed;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;background:#070b11}.titleScreen{background:linear-gradient(90deg,#05080eeb,#05080e55),url('')}.titleInner{width:min(980px,90vw);display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:center}.titleCopy{position:relative;z-index:1}.kicker{font:10px 'DM Mono';letter-spacing:.25em;color:var(--gold)}h1{font-size:clamp(64px,11vw,132px);line-height:.77;letter-spacing:-.03em;margin:22px 0 20px;font-weight:800}.titleCopy p{font-size:18px;line-height:1.3;color:#b1b8bd;max-width:410px}.titleImage{height:min(68vh,550px);position:relative;background:radial-gradient(ellipse at 54% 76%,#25313a 0,#111922 31%,#080d14 64%);border:1px solid #ffffff17;overflow:hidden}.moon{position:absolute;width:130px;height:130px;border-radius:50%;background:#c9c4aa;opacity:.75;top:11%;right:18%;box-shadow:0 0 70px #dfcf9e55}.silhouette{position:absolute;bottom:-4%;left:25%;width:48%;height:80%;background:linear-gradient(90deg,#090d11,#171d21 45%,#080b10);clip-path:polygon(15% 100%,19% 46%,7% 31%,21% 39%,30% 6%,36% 0,43% 20%,52% 6%,61% 22%,71% 34%,89% 31%,77% 47%,81% 100%)}.cityline{position:absolute;bottom:0;height:35%;width:100%;background:linear-gradient(transparent,#070a10 48%);}.cityline:before{content:'';position:absolute;inset:20% 0 0;background:repeating-linear-gradient(90deg,#090d13 0 24px,transparent 24px 37px,#0b1017 37px 54px,transparent 54px 75px);clip-path:polygon(0 40%,8% 40%,8% 20%,17% 20%,17% 50%,26% 50%,26% 0,35% 0,35% 38%,48% 38%,48% 22%,57% 22%,57% 44%,66% 44%,66% 5%,77% 5%,77% 42%,89% 42%,89% 25%,100% 25%,100% 100%,0 100%)}button{font-family:inherit;cursor:pointer}.primary{border:0;background:var(--gold);color:#111;padding:13px 22px;font-size:13px;font-weight:700;letter-spacing:.15em;text-transform:uppercase;margin-top:12px}.primary:hover{background:#f3ce7b}.sub{font:10px 'DM Mono';color:#89929a;letter-spacing:.1em;margin-top:14px}.storyScreen,.endScreen{display:none;background:radial-gradient(ellipse,#151d27,#070b11 67%)}.storyScreen.show,.endScreen.show{display:flex}.storyCard{width:min(750px,90vw);max-height:86vh;overflow-y:auto;padding:32px;border:1px solid #ffffff25;background:#080d15e8;box-shadow:0 24px 100px #000}.storyCard::-webkit-scrollbar{width:5px}.storyCard::-webkit-scrollbar-thumb{background:#e5b85c77}.storyScreen{padding:18px}.bottom{display:none}.mobileControls{display:flex;bottom:max(18px,env(safe-area-inset-bottom));padding:0 24px}.touchBtn:active,.actions button:active{background:#e5b85c55;transform:scale(.96)}button{user-select:none;-webkit-user-select:none}.storyDate{font:10px 'DM Mono';color:var(--gold);letter-spacing:.2em}.storyCard h2{font-size:40px;margin:9px 0 15px;line-height:1}.storyCard p{font-size:18px;color:#c1c5c6;line-height:1.42;margin:0 0 13px}.storyCard p strong{color:#fff}.quote{border-left:2px solid var(--gold);padding:4px 0 4px 15px;margin:16px 0;color:#e4e0d7;font-size:20px}.storyControls{display:flex;justify-content:space-between;align-items:center;margin-top:20px}.progress{font:10px 'DM Mono';color:#a1a8ad;letter-spacing:.15em}.endScreen{text-align:center}.endScreen h2{font-size:60px;margin:8px}.endScreen p{font-size:18px;color:#aeb5bb;max-width:490px;margin:10px auto}.mobileControls{display:none;position:fixed;z-index:5;inset:auto 0 18px;pointer-events:none;justify-content:space-between;padding:0 20px}.pad{display:grid;grid-template-columns:44px 44px 44px;grid-template-rows:44px 44px 44px;gap:3px;pointer-events:auto}.touchBtn{border:1px solid #ffffff3b;background:#08101bcc;color:#fff;font:14px 'DM Mono';border-radius:8px;touch-action:none}.up{grid-column:2}.left{grid-column:1;grid-row:2}.down{grid-column:2;grid-row:2}.right{grid-column:3;grid-row:2}.actions{display:flex;align-items:end;gap:8px;pointer-events:auto}.combatOnly{display:none}.combat-mode .combatOnly{display:block}.combat-mode #touchInteract{display:none}.actions button{height:56px;min-width:58px;border-radius:50%;font-size:11px;color:#fff;border:1px solid #ffffff55;background:#08101bd9;touch-action:none}.actions .act{border-color:#e5b85caa;color:var(--gold)}@media(max-width:700px){.topbar{top:14px;left:16px;right:16px}.objective{left:16px;top:75px;width:180px}.objective h2{font-size:17px}.objective p{font-size:12px}.titleInner{grid-template-columns:1fr;gap:0}.titleImage{position:absolute;inset:13% 0 0 24%;height:87%;opacity:.56;border:0}.titleCopy{padding-top:30vh}.titleCopy p{font-size:16px;max-width:300px}.titleCopy h1{font-size:76px}.status{padding:8px;font-size:8px}.bottom{left:16px;bottom:15px;display:none}.toast{right:16px;bottom:15px;font-size:9px}.mobileControls{display:flex}.interact{bottom:29%;font-size:12px}.dialogue{padding:20px 20px 35px}.line{font-size:20px}.storyCard{padding:23px}.storyCard h2{font-size:34px}.storyCard p{font-size:16px}.titleScreen{overflow:hidden}}
.combatHud{display:none;position:absolute;top:88px;right:30px;width:220px;padding:13px 15px;background:#080d15d9;border:1px solid #ffffff24;font:10px 'DM Mono';letter-spacing:.12em}.combatHud.show{display:block}.fightTitle{display:flex;justify-content:space-between;color:#aab1b9;font-size:9px}.fightTitle b{color:var(--gold);font-weight:400}.healthLabel,.enemyLabel{margin:12px 0 5px;color:#e8e4da}.healthTrack,.enemyTrack{height:7px;background:#ffffff20;overflow:hidden}.healthFill,.enemyFill{height:100%;width:100%;background:#c74b43;transition:width .2s}.healthFill{background:#d6aa59}.enemyLabel{margin-top:10px}.enemyFill{background:#ca5548}.fightTip{color:#9ba4ad;font-size:8px;margin-top:12px;line-height:1.6}.enemyBillboard{position:absolute;z-index:3;pointer-events:none;transform:translate(-50%,-50%);width:48px;height:4px;background:#111a;border:1px solid #ffffff45}.enemyBillboard i{display:block;height:100%;background:#db594d}.combatHud~.bottom{display:none}.combatHud.show~#controlsHint{display:none}.combatHud.show~.toast{display:block}@media(max-width:700px){.combatHud{top:68px;right:14px;width:160px;padding:10px}.fightTip{font-size:7px}.fightTitle{font-size:8px}.healthLabel,.enemyLabel{margin-top:8px}.combatHud.show~.toast{bottom:150px;right:16px}.endScreen h2{font-size:42px}}
</style>
</head>
<body><div class="grain"></div><div class="vignette"></div><div id="game"></div>
<div class="hud" id="hud" style="display:none"><div class="topbar"><div><div class="brand">WAYNE / THE FIRST NIGHT</div><div class="chapter">CHAPTER 01 — THE CAVE</div></div><div class="status">WAYNE ESTATE &nbsp;·&nbsp; <b id="timeLabel">02:14 AM</b></div></div><div class="objective"><div class="eyebrow">Current objective</div><h2 id="objectiveTitle">Explore the cave</h2><p id="objectiveText">Find the equipment Alfred left for you.</p></div><div class="bottom" id="controlsHint"><span class="key">W A S D</span> MOVE <span class="key">E</span> INTERACT <span class="key">MOUSE</span> LOOK</div><div class="interact" id="interactPrompt">[ E ] &nbsp; INTERACT</div><div class="toast" id="toast">A LONG WAY FROM HOME</div><div class="combatHud" id="combatHud"><div class="fightTitle"><span>GOTHAM / EAST END</span><b id="waveLabel">FIRST PATROL</b></div><div class="healthLabel">BRUCE <span id="healthValue">100</span></div><div class="healthTrack"><div class="healthFill" id="healthFill"></div></div><div class="enemyLabel" id="enemyLabel">THREATS 3</div><div class="enemyTrack"><div class="enemyFill" id="enemyFill"></div></div><div class="fightTip" id="fightTip">F / HIT&nbsp; · &nbsp;R / GUARD&nbsp; · &nbsp;SHIFT / DODGE</div></div></div>
<div class="mobileControls" id="mobileControls"><div class="pad"><button class="touchBtn up" data-key="w">▲</button><button class="touchBtn left" data-key="a">◀</button><button class="touchBtn down" data-key="s">▼</button><button class="touchBtn right" data-key="d">▶</button></div><div class="actions"><button id="touchRun" data-key="shift">RUN</button><button id="touchGuard" class="combatOnly" data-key="r">GUARD</button><button id="touchHit" class="combatOnly act">HIT</button><button class="act" id="touchInteract">USE</button></div></div>
<div class="dialogue" id="dialogue"><div class="speaker" id="speaker">ALFRED</div><div class="line" id="line"></div><div class="continue">TAP OR PRESS ENTER TO CONTINUE &nbsp; ›</div></div>
<div class="titleScreen" id="title"><div class="titleInner"><div class="titleCopy"><div class="kicker">A STORY IN THE SHADOWS</div><h1>THE<br>FIRST<br>NIGHT.</h1><p>One man. One promise. A darkness waiting to be shaped.</p><button class="primary" id="begin">Begin the story &nbsp; →</button><div class="sub">WASD / ARROWS OR THE ON-SCREEN PAD TO WALK &nbsp;·&nbsp; E / USE TO INTERACT</div></div><div class="titleImage"><div class="moon"></div><div class="silhouette"></div><div class="cityline"></div></div></div></div>
<div class="storyScreen" id="story"><div class="storyCard"><div class="storyDate" id="storyDate">GOTHAM CITY · 1982</div><h2 id="storyTitle">A night at the movies</h2><div id="storyText"></div><div class="storyControls"><div class="progress" id="storyProgress">01 / 05</div><button class="primary" id="storyNext">Continue →</button></div></div></div>
<div class="endScreen" id="ending"><div><div class="kicker" id="resultKicker">THE FIRST NIGHT</div><h2 id="resultTitle">The work begins.</h2><p id="resultText">The cave is ready. The tools are waiting. Gotham is out there—and tonight, Bruce Wayne finally has a way to answer it.</p><button class="primary" id="playAgain">Play again</button></div></div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const $=s=>document.querySelector(s), game=$('#game');
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.4));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=false;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;game.appendChild(renderer.domElement);
const scene=new THREE.Scene();scene.background=new THREE.Color(0x080d14);scene.fog=new THREE.FogExp2(0x080d14,.023);
const camera=new THREE.PerspectiveCamera(57,innerWidth/innerHeight,.1,130);camera.position.set(0,5,10);
scene.add(new THREE.HemisphereLight(0x8097ae,0x151312,1.35));const moonLight=new THREE.DirectionalLight(0x879bb4,1.7);moonLight.position.set(-8,14,8);moonLight.castShadow=true;scene.add(moonLight);
const warm=new THREE.PointLight(0xffba63,18,18);warm.position.set(-2,3,1);scene.add(warm);const blue=new THREE.PointLight(0x4786ba,20,22);blue.position.set(5,4,-8);scene.add(blue);
const mat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const rock=mat(0x22272b),rock2=mat(0x323535),floorMat=mat(0x191d20,.48),dark=mat(0x080b0f,.34,.65),steel=mat(0x59636a,.35,.72),gold=mat(0xc4934d,.35,.65),cloth=mat(0x101b23),batmat=mat(0x11161b,.46,.3),blueGlow=new THREE.MeshBasicMaterial({color:0x47a4dc});
function mesh(geo,material,x,y,z,sx=1,sy=1,sz=1,shadows=true){let o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=shadows;o.receiveShadow=true;scene.add(o);return o}
// broad cave floor and scattered, hand-built rock walls
mesh(new THREE.CylinderGeometry(23,23,1,48),floorMat,0,-.55,0,1,.42,1);
for(let i=0;i<42;i++){let a=i/42*Math.PI*2,r=15+Math.sin(i*12.3)*2.1,h=3+Math.sin(i*4.17)*2.3;let o=mesh(new THREE.DodecahedronGeometry(1,1),i%3?rock:rock2,Math.cos(a)*r,h/2-1.6,Math.sin(a)*r,2.4+Math.sin(i)*1.3,h,2.3+Math.cos(i*3)*1.2);o.rotation.set(i*.3,i*.7,i*.22)}
// jagged ceiling canopy
for(let i=0;i<22;i++){let a=i/22*Math.PI*2,r=12+(i%3)*1.4;let o=mesh(new THREE.DodecahedronGeometry(1,1),rock,Math.cos(a)*r,7+Math.sin(i*4)*1,Math.sin(a)*r,3.8,1.9,3.2);o.rotation.set(.4,i,.2)}
// stalactites
for(let i=0;i<33;i++){let a=Math.random()*6.28,r=3+Math.random()*10,h=1+Math.random()*2.2;mesh(new THREE.ConeGeometry(.28+Math.random()*.3,h,5),rock2,Math.cos(a)*r,6.6-h/2,Math.sin(a)*r,1,1,1)}
// raised central platform
mesh(new THREE.CylinderGeometry(7.5,8,1.15,12),mat(0x262b2c),0,.05,-2,1,1,1);mesh(new THREE.CylinderGeometry(6.7,7,0.12,12),dark,0,.68,-2,1,1,1);
// equipment bays with luminous lines
function box(x,y,z,sx,sy,sz,m){return mesh(new THREE.BoxGeometry(sx,sy,sz),m,x,y,z)}
// workbench
box(-6,1.1,-3,4.2,.35,1.5,mat(0x302a23));for(let x of [-7.8,-4.2])for(let z of [-3.5,-2.5])box(x,.35,z,.18,1.5,.18,dark);
for(let i=0;i<3;i++){box(-7.3+i*1.3,1.36,-3,0.38,.13,.35,steel);box(-7.3+i*1.3,1.45,-3,.12,.04,.12,gold)}
// console station
box(-3.3,1.12,-9,4.4,1.9,.65,dark);box(-3.3,2.2,-9,3.7,.1,.4,steel);for(let i=0;i<3;i++){let sc=box(-4.4+i*1.1,2.82,-9,.85,1.05,.13,mat(0x101c25,.3,.2));sc.rotation.x=-.18;box(-4.4+i*1.1,2.82,-8.91,.68,.78,.02,blueGlow)}
// computer tower and keyboard
box(-3.3,1.5,-8,2.8,.12,1,steel);
// suit display pod
const pod=box(3.3,3.05,-6,.24,5.3,.24,gold);box(5.3,3.05,-6,.24,5.3,.24,gold);box(4.3,5.68,-6,2.2,.16,.22,gold);box(4.3,.53,-6,2.2,.18,.22,gold);
// mannequin body shape
const torso=mesh(new THREE.CapsuleGeometry(.66,1.7,6,9),batmat,4.3,2.9,-6);const head=mesh(new THREE.SphereGeometry(.48,16,12),mat(0x77736a),4.3,4.35,-6);const cape=mesh(new THREE.ConeGeometry(1.35,2.8,4),batmat,4.3,1.9,-5.7);cape.rotation.x=Math.PI;cape.rotation.z=Math.PI/4;
// bat ears
for(let x of [4.02,4.58]){let ear=mesh(new THREE.ConeGeometry(.12,.48,4),batmat,x,4.85,-6);ear.rotation.z=x<4.3?-.22:.22}
// armor crate / gear table
box(7,1,-1,3.6,.5,2.1,mat(0x252a2d));for(let x of [5.5,8.5])for(let z of [-1.8,-.2])box(x,.45,z,.17,.85,.17,dark);
// batmobile centerpiece at right
const car=new THREE.Group();scene.add(car);car.position.set(9,.2,-8);car.rotation.y=-.48;
const cm=mat(0x10161b,.28,.7), glass=mat(0x172b38,.18,.55);function carbox(g,m,x,y,z,sx,sy,sz){const o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;car.add(o);return o}
carbox(new THREE.BoxGeometry(1,1,1),cm,0,.75,0,5.4,.72,2.4);carbox(new THREE.BoxGeometry(1,1,1),cm,-.35,1.3,-.05,2.7,.65,1.9);const windshield=carbox(new THREE.BoxGeometry(1,1,1),glass,-.15,1.72,0,1.9,.45,1.6);windshield.rotation.z=-.22;
carbox(new THREE.ConeGeometry(.6,2.4,5),cm,-3.6,.74,0,1,.7,1);carbox(new THREE.CylinderGeometry(.24,.24,.14,16),blueGlow,2.75,.77,-.55,1,1,1);carbox(new THREE.CylinderGeometry(.24,.24,.14,16),blueGlow,2.75,.77,.55,1,1,1);
for(let x of [-1.7,1.65])for(let z of [-1.25,1.25]){let w=carbox(new THREE.CylinderGeometry(.64,.64,.34,16),dark,x,.57,z,1,1,1);w.rotation.x=Math.PI/2;let hub=carbox(new THREE.CylinderGeometry(.29,.29,.36,12),steel,x,.57,z,1,1,1);hub.rotation.x=Math.PI/2}
// elevator / lift and pillars
box(0,.3,9,4,.5,3,dark);for(let x of [-1.7,1.7]){box(x,3.3,9,.16,6.3,.16,steel);box(x,6.45,9,.5,.18,.25,gold)}
// cave water pools and stepping stones
for(let i=0;i<7;i++){let a=i*1.4;let p=mesh(new THREE.CircleGeometry(1.2+Math.random(),20),mat(0x1b2b32,.16,.55),-11+Math.cos(a)*2,-.01,5+Math.sin(a)*2,1,.35,1,false);p.rotation.x=-Math.PI/2;}
// lamps
for(let i=0;i<9;i++){let a=i*6.28/9,x=Math.cos(a)*11,z=Math.sin(a)*11;let l=new THREE.PointLight(i%3===0?0xd89a4e:0x477da0,3.2,9);l.position.set(x,2,z);scene.add(l);mesh(new THREE.SphereGeometry(.12,8,8),i%3===0?gold:blueGlow,x,2,z,.8,.8,.8,false)}
// character
const player=new THREE.Group();scene.add(player);player.position.set(0,0,5);player.rotation.y=Math.PI;
const body= new THREE.Group();player.add(body);const suit=mat(0x202c33,.65,.16),skin=mat(0xa58c72);let torsoP=new THREE.Mesh(new THREE.CapsuleGeometry(.33,.85,4,8),suit);torsoP.position.y=1.15;torsoP.castShadow=true;body.add(torsoP);let headP=new THREE.Mesh(new THREE.SphereGeometry(.23,12,10),skin);headP.position.y=1.88;headP.castShadow=true;body.add(headP);for(let x of [-.19,.19]){let leg=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.65,3,6),dark);leg.position.set(x,.48,0);leg.castShadow=true;body.add(leg);let arm=new THREE.Mesh(new THREE.CapsuleGeometry(.11,.64,3,6),suit);arm.position.set(x*2,1.22,0);arm.rotation.z=x<0?-.12:.12;arm.castShadow=true;body.add(arm)}
// objective points and visible props
const items=[
{id:'book',name:'Self-defense field guide',pos:new THREE.Vector3(-6,1.75,-3),desc:'A book on self-defense',done:false,model:null},
{id:'batarang',name:'Batarangs',pos:new THREE.Vector3(7,1.25,-1),desc:'A set of precision batarangs',done:false,model:null},
{id:'smoke',name:'Smoke pellets',pos:new THREE.Vector3(6.3,1.25,-1.7),desc:'Smoke pellets',done:false,model:null},
{id:'grapple',name:'Grapple gun',pos:new THREE.Vector3(7.8,1.25,-1),desc:'A prototype grapple gun',done:false,model:null},
{id:'suit',name:'Suit up',pos:new THREE.Vector3(4.3,1,-6),desc:'The suit display',done:false,model:null},
{id:'car',name:'The Batmobile',pos:new THREE.Vector3(9,1,-8),desc:'The Batmobile',done:false,model:null},
{id:'lift',name:'Elevator',pos:new THREE.Vector3(0,1,9),desc:'The cave elevator',done:false,model:null}
